//! Trace-derived sandbox profile for vm.
//!
//! Initially generated by sandbox_profiler.
//!
//! Observed filesystem accesses:
//! - /etc/ld.so.cache (RO)
//! - /proc/self/comm (RW)
//! - /proc/self/maps (RO)
//! - /proc/sys/vm/overcommit_memory (RO)
//! - /sys/devices/system/cpu/online (RO)
//! - /usr/lib/x86_64-linux-gnu/libc.so.6 (RO)
//! - /usr/lib/x86_64-linux-gnu/libgcc_s.so.1 (RO)
//! - /usr/lib/x86_64-linux-gnu/libm.so.6 (RO)
//!
//! Observed network accesses:
//! - None.
//!
//! Observed syscalls:
//! - clone3
//! - close
//! - execve
//! - fcntl
//! - openat
//! - recvfrom
//! - recvmsg
//! - sendmsg
//! - sendto
//!
//! Filesystem policy access omissions:
//! - /proc/self/comm is provided by the sandbox's implicit /proc mount.
//! - /proc/self/maps is provided by the sandbox's implicit /proc mount.
//! - /proc/sys/vm/overcommit_memory is provided by the sandbox's implicit /proc mount.
//!
//! Syscalls denied by policy but used by the worker:
//! - clone3
//! - execve

use crate::Builder;
use crate::Network;
use crate::Profile;
use crate::Syscalls;

/// Profile derived from observed worker behavior.
///
/// Leaves `mbind` available for host NUMA placement of guest RAM.
/// On Linux, includes existing resolver targets and the SEV and legacy VFIO
/// container nodes. Optional paths must exist when the profile is built.
pub fn vm_worker() -> Builder {
    let profile = Profile::deny_all()
        .name("vm_worker")
        .read("/etc")
        .read("/sys/devices")
        .read_exec("/usr/lib")
        .syscalls(Syscalls::deny([
            "bpf",
            "chroot",
            "clone3",
            #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
            "create_module",
            "delete_module",
            "execve",
            "finit_module",
            #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
            "fork",
            "fsconfig",
            "fsmount",
            "fsopen",
            "fspick",
            "init_module",
            #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
            "ioperm",
            #[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
            "iopl",
            "kexec_file_load",
            "kexec_load",
            "mount",
            "mount_setattr",
            "move_mount",
            "open_tree",
            "pivot_root",
            "process_vm_readv",
            "process_vm_writev",
            "ptrace",
            "reboot",
            "setns",
            "umount2",
            "unshare",
            "userfaultfd",
            "waitid",
            "acct",
            "add_key",
            "kcmp",
            "keyctl",
            "request_key",
        ]))
        .network(Network::Unrestricted);

    #[cfg(target_os = "linux")]
    let profile = {
        let mut profile = profile;
        if let Some(target) = resolver_target() {
            profile = profile.read(target);
        }
        if std::path::Path::new("/sys/bus/pci/devices").exists() {
            profile = profile.read("/sys/bus/pci/devices");
        }
        for path in ["/dev/sev", "/dev/vfio/vfio"] {
            if std::path::Path::new(path).exists() {
                profile = profile.device(path);
            }
        }
        profile
    };

    profile
}

#[cfg(target_os = "linux")]
fn resolver_target() -> Option<std::path::PathBuf> {
    use std::path::Component;
    use std::path::PathBuf;

    let mut path = PathBuf::from("/etc/resolv.conf");
    std::fs::metadata(&path).ok()?;
    for _ in 0..40 {
        let (prefix, target) = path
            .ancestors()
            .collect::<Vec<_>>()
            .into_iter()
            .rev()
            .find_map(|prefix| {
                std::fs::read_link(prefix)
                    .ok()
                    .map(|target| (prefix.to_path_buf(), target))
            })?;
        let target = prefix
            .parent()?
            .join(target)
            .join(path.strip_prefix(&prefix).ok()?);
        path.clear();
        for component in target.components() {
            if component == Component::ParentDir {
                path.pop();
            } else {
                path.push(component);
            }
        }
        // Bind the first path outside /etc, not just its canonical target:
        // /etc's symlinks may name aliases such as /var/run or another link.
        if !path.starts_with("/etc") {
            return Some(path);
        }
    }
    None
}

#[cfg(all(test, target_os = "linux"))]
mod tests {
    use super::*;
    use test_with_tracing::test;

    #[test]
    fn syscall_names_resolve() {
        let profile = vm_worker().build();
        let Syscalls::Deny(names) = profile.inner.syscalls else {
            panic!("VM worker must use syscall filtering");
        };
        for name in names {
            assert!(
                crate::nr_for_name(&name).is_some(),
                "VM worker syscall does not resolve: {name}",
            );
        }
    }
}
